intro a b h;
apply Nat.add_le_add_left;
exact h

begin
  intros n h,
  have h': (n * n) % 4 ≠ 2,
  { cases (n mod 4) with r,
    all_goals {
      cases r,
      all_goals {
        exact (by simp [mod4, r])
      }
    }
  },
  exact h',
end

intro n h,
by_cases h0: n = 0;
  { have h1: (0 * 0) % 4 = 0 := by simp;
    exact (neq_of_false h1 2) }
  { have h0: n = 1;
    have h1: (1 * 1) % 4 = 1 := by simp;
    exact (neq_of_false h1 2) }
  { have h0: n = 2;
    have h1: (2 * 2) % 4 = 0 := by simp;
    exact (neq_of_false h1 2) }
  { have h0: n = 3;
    have h1: (3 * 3) % 4 = 1 := by simp;
    exact (neq_of_false h1 2) }
  { have h0: n = 4;
    have h1: (4 * 4) % 4 = 0 := by simp;
    exact (neq_of_false h1 2) }
  { have h0: n = 5;
    have h1: (5 * 5) % 4 = 1 := by simp;
    exact (neq_of_false h1 2) }
  { have h0: n = 6;
    have h1: (6 * 6) % 4 = 0 := by simp;
    exact (neq_of_false h1 2) }
  { have h0: n = 7;
    have h1: (7 * 7) % 4 = 1 := by simp;
    exact (neq_of_false h1 2) }
  { have h0: n = 8;
    have h1: (8 * 8) % 4 = 0 := by simp;
    exact (neq_of_false h1 2) }
  { have h0: n = 9;
    have h1: (9 * 9) % 4 = 1 := by simp;
    exact (neq_of_false h1 2) }
  { have h0: n = 10;
    have h1: (10 * 10) % 4 = 0 := by simp;
    exact (neq_of_false h1 2) }
  { have h0: n = 11;
    have h1: (11 * 11) % 4 = 1 := by simp;
    exact (neq_of_false h1 2) }
  { have h1: n < 12 := h;
    have h2: n = 12 := by exfalso; contradiction h1; }
  { exact (False.elim h2) }

by cases n;
  cases n with n; 
  simp [Nat.mod_eq_mod, Nat.mod_zero, Nat.mod_one];
  rw [Nat.mod_eq_mod, Nat.mod_one];
  rw [Nat.mod_eq_mod, Nat.mod_zero];
  rw [Nat.mod_eq_mod, Nat.mod_one];
  rw [Nat.mod_eq_mod, Nat.mod_zero];
  sorry

intro n h,
cases n,
  case zero {
    have h1 : (0 * 0 + 1) % 5 = 1 := rfl,
    exact ne_of_gt 1 0
  },
  case one {
    have h1 : (1 * 1 + 1) % 5 = 2 := rfl,
    exact ne_of_gt 2 0
  }
